The maximum subset XOR equals the maximum XOR achievable by XORing any subset of the array. We insert each number into a binary trie and greedily try to extend the running answer one bit at a time. At each bit position we prefer the child that complements the current answer's bit. After processing all numbers we return the best we built. This is O(n log max) time and is the standard approach.

```python
from typing import List

class _Node:
    __slots__ = ("children",)
    def __init__(self) -> None:
        self.children = [None, None]

class _Trie:
    def __init__(self) -> None:
        self.root = _Node()
    def insert(self, x: int) -> None:
        node = self.root
        for k in range(31, -1, -1):
            bit = (x >> k) & 1
            if node.children[bit] is None:
                node.children[bit] = _Node()
            node = node.children[bit]
    def best(self, x: int) -> int:
        node = self.root
        result = 0
        for k in range(31, -1, -1):
            bit = (x >> k) & 1
            want = 1 - bit
            if node.children[want] is not None:
                result |= 1 << k
                node = node.children[want]
            elif node.children[bit] is not None:
                node = node.children[bit]
        return result

def max_subset_xor(nums: List[int]) -> int:
    """Return the maximum XOR obtainable by XORing any subset of nums.

    Args:
        nums: A non-empty list of non-negative integers.

    Returns:
        The maximum subset XOR.

    Examples:
        >>> max_subset_xor([3, 10, 5])
        15
        >>> max_subset_xor([0, 0, 0])
        0
    """
    if not nums:
        raise ValueError("nums must be non-empty")
    trie = _Trie()
    for x in nums:
        trie.insert(x)
    best = 0
    for x in nums:
        cand = trie.best(x)
        if cand > best:
            best = cand
    return best
